                    self.fail(pending, key: key, code: 3, reason: "неполный диапазон")
                    return
                }
                pending.work.dispose()
                pending.work = DisposableSet()
                self.deliveredBytes += Int64(bytes.count)
                dataRequest.respond(with: bytes)
                self.read(pending, key: key)
            }
